import{_ as a,o as s,c as e,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"AI 产品设计边界","description":"AI 产品最大的特点是不确定性，设计的核心是管理预期、优雅降级，以及想清楚何时不该用 AI。","frontmatter":{"title":"AI 产品设计边界","description":"AI 产品最大的特点是不确定性，设计的核心是管理预期、优雅降级，以及想清楚何时不该用 AI。"},"headers":[],"relativePath":"ai/product-design.md","filePath":"ai/product-design.md","lastUpdated":1786271684000}'),n={name:"ai/product-design.md"};function d(i,t,l,r,p,u){return s(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="ai-产品设计边界" tabindex="-1">AI 产品设计边界 <a class="header-anchor" href="#ai-产品设计边界" aria-label="Permalink to &quot;AI 产品设计边界&quot;">​</a></h1><p>传统软件是确定性的：点同一个按钮，得到同一个结果。AI 产品不是——同样的输入，模型可能给出不同的、甚至错误的回答。这种不确定性是 AI 产品的根本约束，所有产品设计决策都围绕它展开：如何向用户传达&quot;这可能不准&quot;、如何在它失败时优雅降级、什么时候该让人介入、以及最关键的——哪些场景根本不该用 AI。把 AI 当万能锤子，是产品翻车的开始。</p><h2 id="先接受-ai-不能-100-可靠" tabindex="-1">先接受：AI 不能 100% 可靠 <a class="header-anchor" href="#先接受-ai-不能-100-可靠" aria-label="Permalink to &quot;先接受：AI 不能 100% 可靠&quot;">​</a></h2><p>这是设计 AI 产品的第一原则。模型会幻觉、会跑题、会在不该自信的地方很自信。如果产品假装它&quot;永远对&quot;，用户照着错的结果操作，损失就发生了。</p><table tabindex="0"><thead><tr><th>信任度</th><th>设计取向</th></tr></thead><tbody><tr><td>高可靠要求（医疗诊断、法律结论）</td><td>AI 仅辅助，最终必须人工确认</td></tr><tr><td>中等（写作助手、摘要、推荐）</td><td>AI 主导，用户可改，标注&quot;AI 生成&quot;</td></tr><tr><td>容错（娱乐、灵感、草稿）</td><td>AI 全自动，失败成本低</td></tr></tbody></table><p><strong>产品设计的核心问题不是&quot;模型能做到吗&quot;，而是&quot;它错了的代价我承受得起吗&quot;</strong>。承受不起的，就必须加人工关卡或确定性兜底。</p><h2 id="人机协作-vs-全自动" tabindex="-1">人机协作 vs 全自动 <a class="header-anchor" href="#人机协作-vs-全自动" aria-label="Permalink to &quot;人机协作 vs 全自动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>适用</th><th>体验</th></tr></thead><tbody><tr><td>全自动</td><td>失败成本低、可批量、可重做</td><td>快，但出错用户没机会拦</td></tr><tr><td>人审后执行</td><td>高风险、不可逆动作</td><td>稳，但有延迟和人力成本</td></tr><tr><td>AI 草稿 + 人编辑</td><td>创作类、内容生成</td><td>平衡，保留人的最终控制权</td></tr><tr><td>Copilot 协助</td><td>专业工具、代码、办公</td><td>人主导，AI 加速，可控性最高</td></tr></tbody></table><p>一个务实的经验：<strong>默认偏向人机协作</strong>。让 AI 干&quot;费时但不致命&quot;的活（草拟、抽取、初筛），让人干&quot;判断和拍板&quot;的活。全自动只放在那些&quot;错了也能轻易撤销&quot;的场景。</p><h2 id="延迟与体验" tabindex="-1">延迟与体验 <a class="header-anchor" href="#延迟与体验" aria-label="Permalink to &quot;延迟与体验&quot;">​</a></h2><p>AI 调用慢，一次几秒到几十秒是常态。这对用户体验是巨大挑战：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统接口：200ms 内返回，用户感知&quot;即时&quot;</span></span>
<span class="line"><span>AI 接口：3-15s 才返回，用户感知&quot;卡住了&quot;</span></span></code></pre></div><p>应对手段：</p><ul><li><strong>流式输出</strong>（streaming）：边生成边返回，让用户看到&quot;在动&quot;，体感延迟大幅下降。</li><li><strong>分阶段反馈</strong>：先回一句&quot;正在思考&quot;，再给结果，避免黑屏等待。</li><li><strong>预生成与缓存</strong>：高频问题可预计算或缓存，命中即秒回。</li><li><strong>异步任务</strong>：超长任务（报告生成、视频处理）改成后台跑 + 完成通知。</li></ul><blockquote><p>延迟不只是技术指标，是产品体验的一部分。同样的准确率，流式 + 实时反馈的版本，用户满意度会高一大截。</p></blockquote><h2 id="失败要优雅降级" tabindex="-1">失败要优雅降级 <a class="header-anchor" href="#失败要优雅降级" aria-label="Permalink to &quot;失败要优雅降级&quot;">​</a></h2><p>模型会失败，关键是失败时不要把烂摊子甩给用户。降级链路：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型超时/出错</span></span>
<span class="line"><span>  → 重试（有限次）</span></span>
<span class="line"><span>  → 仍失败 → 返回兜底文案 + 引导用户重试或转人工</span></span>
<span class="line"><span>  → 绝不返回半截错误堆栈或&quot;我不知道&quot;就结束</span></span></code></pre></div><p>兜底要设计得像产品的一部分，而不是系统报错。&quot;这个问题我暂时答不了，已转给人工，预计 X 分钟回复&quot;远好过 <code>500 Internal Server Error</code>。</p><h2 id="用户预期管理" tabindex="-1">用户预期管理 <a class="header-anchor" href="#用户预期管理" aria-label="Permalink to &quot;用户预期管理&quot;">​</a></h2><p>AI 产品最容易翻车的地方，是承诺了做不到的事。文案、引导、示例都在塑造用户预期：</p><table tabindex="0"><thead><tr><th>做法</th><th>效果</th></tr></thead><tbody><tr><td>标注&quot;AI 生成，请核对&quot;</td><td>降低用户对绝对正确的期待</td></tr><tr><td>给出引用/来源</td><td>让用户能自行核验，建立信任</td></tr><tr><td>展示能力边界示例</td><td>让用户知道&quot;它能干什么、不能干什么&quot;</td></tr><tr><td>失败时不掩饰</td><td>坦诚说&quot;没找到&quot;，比硬编一个错答案好</td></tr></tbody></table><blockquote><p>用户对 AI 的信任是消耗品。一次 confident 的错误回答，会毁掉十次正确回答积累的信任。宁可保守，不要吹。</p></blockquote><h2 id="反馈闭环" tabindex="-1">反馈闭环 <a class="header-anchor" href="#反馈闭环" aria-label="Permalink to &quot;反馈闭环&quot;">​</a></h2><p>AI 产品必须有用户反馈通道，而且要闭环用起来：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点&quot;回答没用/有错&quot;</span></span>
<span class="line"><span>  → 记录 bad case</span></span>
<span class="line"><span>  → 进入评测集和护栏优化</span></span>
<span class="line"><span>  → 下一版针对性改进</span></span>
<span class="line"><span>  → 改进效果通过评测验证</span></span></code></pre></div><p>没有闭环，反馈按钮就是装饰。真正有用的产品，会把&quot;用户点了踩&quot;的 case 当作最高优先级的改进信号，而不是一个埋点数据。</p><h2 id="什么时候不该用-ai" tabindex="-1">什么时候不该用 AI <a class="header-anchor" href="#什么时候不该用-ai" aria-label="Permalink to &quot;什么时候不该用 AI&quot;">​</a></h2><p>这是设计师最该想清楚的问题。AI 不是默认选项，它有明确的适用边界：</p><ul><li><strong>规则明确、需要 100% 准确</strong>：用传统代码，别上模型。算账、权限、库存这种，错了出事。</li><li><strong>流量大、成本敏感</strong>：每次调用都要钱，规模上来账单可能失控。</li><li><strong>延迟要求极高</strong>：实时交互 &lt;200ms 的场景，模型跟不上。</li><li><strong>可解释性要求强</strong>：监管要求每个决策可审计、可解释，黑盒模型难满足。</li><li><strong>用户期待确定性</strong>：同样的操作必须得到同样结果，模型的波动会让用户困惑。</li></ul><p>判断标准很简单：<strong>如果一个确定性的规则或传统算法能解决，就先用它；只有当问题本质上是&quot;模糊的、语义的、需要泛化的&quot;，才考虑 AI</strong>。</p><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>产品是否坦诚传达了&quot;AI 可能不准&quot;，还是假装它永远对？</li><li>失败时是否有优雅降级，而不是甩给用户一个报错？</li><li>高风险动作是否有人工关卡或确定性兜底？</li><li>延迟是否用流式/反馈手段缓解，体感是否可接受？</li><li>用户反馈是否形成闭环，bad case 能否驱动改进？</li><li>这个场景真的需要 AI 吗，还是传统方案更稳更便宜？</li></ul>`,33)])])}const q=a(n,[["render",d]]);export{c as __pageData,q as default};
